it('treats legacy items without price as zero', () => {
  const total = calculateTotal([
    { id: 'legacy-1', quantity: 2 },
    { id: 'sku-2', quantity: 1, price: { amount: 1250, currency: 'EUR' } },
  ])

  expect(total).toBe(1250)
})

